const originals = new WeakMap(); function applyLanguage(root = document.body) { const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT); let n; while (n = w.nextNode()) { if (!originals.has(n)) originals.set(n, n.nodeValue); const o = originals.get(n), t = o.trim(); if (t) n.nodeValue = o.replace(t, uiLang === 'hi' ? (hi[t] || t) : t) } document.documentElement.lang = uiLang === 'hi' ? 'hi' : 'en'; document.querySelector('#langToggle').textContent = uiLang === 'hi' ? 'English' : 'हिन्दी'; if (typeof setAuthMode === 'function' && document.querySelector('#authScreen').classList.contains('open')) setAuthMode(currentAuthMode); if (typeof refreshSessionUI === 'function') refreshSessionUI(); const search = document.querySelector('#adminSearch'); if (search) search.placeholder = uiLang === 'hi' ? 'नाम, ईमेल, गाँव खोजें' : 'Search name, email, village'; const formLang = document.querySelector('#formLangToggle'); if (formLang) formLang.textContent = uiLang === 'hi' ? 'English' : 'हिन्दी';['authLangToggle', 'adminLangToggle'].forEach(id => { const b = document.querySelector('#' + id); if (b) b.textContent = uiLang === 'hi' ? 'English' : 'हिन्दी' }); const rr = localStorage.getItem('terraAssessment'); if (rr) { try { const z = JSON.parse(rr); if (z.result) updateDashboard(z.result.score, z.result.breakdown, z.result.status) } catch (e) { } } } document.querySelector('#langToggle').onclick = () => { uiLang = uiLang === 'en' ? 'hi' : 'en'; localStorage.setItem('humusiqLanguage',uiLang); applyLanguage(); if(cropPrediction)renderCropAnalysis(); if (modal.classList.contains('open')) { if (document.querySelector('#content .result')) showResult(); else render(true) } };
function words(pair) { return pair[uiLang === 'hi' ? 1 : 0] }
