    if (['crops','practices','inputs','irrigation','soil','documents','water'].includes(d.type)) { const a=answers[d.type]||(answers[d.type]=[]); body=`<div class="options">${d.opts.map((o,i)=>`<button class="option ${a.includes(i)?'selected':''}" data-multi="${d.type}" data-i="${i}" aria-pressed="${a.includes(i)}">${words(o)}</button>`).join('')}</div>`; if(d.type==='crops') body+=field('cropHistory',uiLang==='hi'?'फसल के नाम':'Crop names','text',uiLang==='hi'?'जैसे गेहूँ, कपास':'e.g. wheat, cotton',answers.cropHistory)+`<div class="formgrid">${field('cropYield',uiLang==='hi'?'औसत पैदावार (वैकल्पिक)':'Typical yield (optional)','number',uiLang==='hi'?'जैसे 18':'e.g. 18',answers.cropYield)}${field('cropSeasons',uiLang==='hi'?'फसल का मौसम (वैकल्पिक)':'Growing season (optional)','text',uiLang==='hi'?'जैसे खरीफ':'e.g. Kharif',answers.cropSeasons)}${field('cropYears',uiLang==='hi'?'कितने वर्षों से (वैकल्पिक)':'Years grown (optional)','number',uiLang==='hi'?'जैसे 3':'e.g. 3',answers.cropYears)}</div>`; if(d.type==='inputs')body+=field('inputDetail',uiLang==='hi'?'इनपुट के रिकॉर्ड / जानकारी (वैकल्पिक)':'Input records or details (optional)','text',uiLang==='hi'?'जैसे खाद की रसीदें':'e.g. fertiliser receipts',answers.inputDetail); if(d.type==='irrigation')body+=field('irrigationDetail',uiLang==='hi'?'पानी का स्रोत / सिंचाई की जानकारी (वैकल्पिक)':'Water source or irrigation details (optional)','text',uiLang==='hi'?'जैसे ट्यूबवेल, तालाब':'e.g. tubewell, pond',answers.irrigationDetail); if(d.type==='soil')body+=field('soilDetail',uiLang==='hi'?'मिट्टी की जानकारी (वैकल्पिक)':'Soil notes (optional)','text',uiLang==='hi'?'जैसे मिट्टी का प्रकार':'e.g. soil type',answers.soilDetail); if(d.type==='water')body+=field('waterDetail',uiLang==='hi'?'पानी की जानकारी (वैकल्पिक)':'Water details (optional)','text','',answers.waterDetail) }
    if (d.type === 'map') body = `<div class="mapinstructions">${uiLang === 'hi' ? 'सीमा के कोनों पर टैप करें। बिंदु हटाने के लिए “Undo” चुनें।' : 'Tap the field corners to sketch its boundary. Use Undo to remove the last point.'}</div><svg id="farmMap" class="farmmap" viewBox="0 0 400 250" role="img" aria-label="${uiLang === 'hi' ? 'खेत की सीमा बनाने का नक्शा' : 'Map sketch area for your field boundary'}"><rect width="400" height="250" rx="15" fill="#e8f0df"/><path d="M0 65 Q90 42 180 72 T400 50 M0 202 Q90 180 200 210 T400 183" fill="none" stroke="#c9d9bb" stroke-width="2"/><path d="M42 0 Q74 90 48 250 M340 0 Q317 110 365 250" fill="none" stroke="#d4ddc5" stroke-width="2"/><path d="M0 125 H400 M200 0 V250" stroke="#d7dfcd" stroke-width="1" stroke-dasharray="5 7"/><polygon id="fieldPoly" points="${answers.boundary.map(p => p.join(',')).join(' ')}" fill="#80a96566" stroke="#4e7948" stroke-width="3"/>${answers.boundary.map(p => `<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="#345f40"/>`).join('')}<text x="15" y="236" font-size="10" fill="#566650">${uiLang === 'hi' ? 'खेत की सीमा का अनुमानित स्केच' : 'Approximate field boundary sketch'}</text></svg><p id="mapArea" class="hint">${answers.boundary.length >= 3 ? (uiLang === 'hi' ? 'सीमा का स्केच सेव हुआ · वास्तविक क्षेत्रफल नहीं' : 'Boundary sketch saved · area not measured') : (uiLang === 'hi' ? 'अभी ' : 'Current points: ') + answers.boundary.length + (uiLang === 'hi' ? ' बिंदु · सीमा पूरी करने के लिए 3 या अधिक जोड़ें' : ' · add 3 or more to close boundary')}</p><div class="mapbuttons"><button class="secondary" id="undoPoint">${uiLang === 'hi' ? '↶ वापस' : '↶ Undo'}</button><button class="secondary" id="clearMap">${uiLang === 'hi' ? 'सीमा साफ़ करें' : 'Clear boundary'}</button></div>`;
    content.innerHTML = `<h3 class="question">${q}</h3><p class="hint">${h}</p>${body}<div class="panelactions"><button class="back" id="prev" ${step === 0 ? 'disabled' : ''}>← ${uiLang === 'hi' ? 'पीछे' : 'Back'}</button><button class="primary" id="next">${step === formSteps.length - 1 ? (uiLang === 'hi' ? 'तैयारी का नतीजा देखें' : 'See readiness result') : (uiLang === 'hi' ? 'आगे बढ़ें →' : 'Continue →')}</button></div>`;
