function polygonArea(points) { if (points.length < 3) return 0; let a = 0; for (let i = 0; i < points.length; i++) { const p = points[i], n = points[(i + 1) % points.length]; a += p[0] * n[1] - n[0] * p[1] } return (Math.abs(a) / 2 / 10000).toFixed(2) }
function assess(){const chosen=(key,noneIndex)=>answers[key].filter(i=>i!==noneIndex).length,land=answers.land,docs=answers.documents,scale=(value,base,max)=>Math.round(value/base*max),basePractice=Math.min(25,chosen('practices',5)*4+(answers.cropHistory?2:0)+(answers.cropYield?2:0)+(answers.cropSeasons?1:0)+(answers.cropYears?1:0)),baseLand=Math.min(15,(Number(land.area)>0?5:0)+(land.tenure!==undefined?4:0)+(land.landType!==undefined?2:0)+(answers.profile.village&&answers.profile.state?2:0)+(answers.boundary.length>=3?2:0)),baseDocuments=Math.min(20,docs.filter(i=>i!==5).length*4),baseSoil=Math.min(15,chosen('soil',5)*3),baseIrrigation=Math.min(15,(answers.irrigation.length?6:0)+(answers.irrigation.some(i=>i===1||i===2)?4:0)+(answers.irrigationDetail?5:0)),baseInputs=Math.min(10,chosen('inputs',5)*2+(answers.inputDetail?4:0)),practice=scale(basePractice,25,readinessWeights.practices),landScore=scale(baseLand,15,readinessWeights.land),documentation=scale(baseDocuments,20,readinessWeights.documents),soilScore=scale(baseSoil,15,readinessWeights.soil),irrigationScore=scale(baseIrrigation,15,readinessWeights.irrigation),inputScore=scale(baseInputs,10,readinessWeights.inputs);return{practice,land:landScore,documents:documentation,soil:soilScore,irrigation:irrigationScore,inputs:inputScore,total:practice+landScore+documentation+soilScore+irrigationScore+inputScore}}
function showResult(){const s=assess(),score=s.total,status=score>=75?'High':score>=50?'Medium':'Low',statusClasses={High:'green',Medium:'yellow',Low:'red'},statusText=uiLang==='hi'?({High:'उच्च',Medium:'मध्यम',Low:'कम'}[status]):status,actions=[];const add=(text,points,category)=>actions.push([text,points,category]);if(!answers.profile.name)add(uiLang==='hi'?'किसान का नाम भरें':'Add the farmer name',3,'land');if(!answers.profile.village||!answers.profile.state)add(uiLang==='hi'?'गाँव और राज्य की जानकारी पूरी करें':'Complete village and state information',3,'land');if(!(Number(answers.land.area)>0)||answers.land.tenure===undefined)add(uiLang==='hi'?'क्षेत्रफल और ज़मीन की व्यवस्था की जानकारी पूरी करें':'Complete farm area and land ownership details',5,'land');if(!answers.crops.length)add(uiLang==='hi'?'उगाई जाने वाली फसलें चुनें':'Select the crops you grow',4,'practice');if(!answers.cropYears||!answers.cropSeasons)add(uiLang==='hi'?'मौसम और खेती के वर्षों का रिकॉर्ड शुरू करें':'Record growing seasons and years of crop history',5,'practice');if(!answers.documents.includes(1))add(uiLang==='hi'?'मिट्टी जाँच रिपोर्ट इकट्ठा करें':'Collect a soil test report',6,'documents');if(!answers.documents.includes(2))add(uiLang==='hi'?'कम से कम 2 वर्षों के फसल और खेत के रिकॉर्ड रखें':'Keep at least two years of crop and field records',6,'documents');if(!answers.documents.includes(0))add(uiLang==='hi'?'ज़मीन के कागज़ इकट्ठा करें':'Collect land documents',4,'documents');if(!answers.soil.includes(0))add(uiLang==='hi'?'मिट्टी की जाँच करवाने पर विचार करें':'Consider arranging a soil test',5,'soil');if(!answers.irrigation.length)add(uiLang==='hi'?'सिंचाई का तरीका और पानी का स्रोत दर्ज करें':'Record irrigation method and water source',5,'irrigation');if(!answers.inputs.length)add(uiLang==='hi'?'खाद और अन्य इनपुट का उपयोग दर्ज करें':'Record fertiliser and other input use',4,'inputs');if(answers.boundary.length<3)add(uiLang==='hi'?'नक्शे पर खेत की सीमा के 3 बिंदु जोड़ें':'Add three points to mark the field boundary',2,'land');const actionCap={practice:readinessWeights.practices,land:readinessWeights.land,documents:readinessWeights.documents,soil:readinessWeights.soil,irrigation:readinessWeights.irrigation,inputs:readinessWeights.inputs};actions.forEach(a=>{const key=a[2],baseMax={practice:25,land:15,documents:20,soil:15,irrigation:15,inputs:10}[key];a[1]=Math.min(Math.ceil(a[1]*actionCap[key]/baseMax),Math.max(0,actionCap[key]-s[key]))});for(let i=actions.length-1;i>=0;i--)if(actions[i][1]<=0)actions.splice(i,1);const category=(name,value,max)=>`<div class="breakrow"><div><b>${name}</b><span>${value} / ${max}</span></div><div class="meter"><span style="width:${(max?Math.round(value/max*100):0)}%"></span></div></div>`,categoryList=category(uiLang==='hi'?'खेती के तरीके':'Practices',s.practice,readinessWeights.practices)+category(uiLang==='hi'?'ज़मीन':'Land',s.land,readinessWeights.land)+category(uiLang==='hi'?'दस्तावेज़':'Documentation',s.documents,readinessWeights.documents)+category(uiLang==='hi'?'मिट्टी':'Soil',s.soil,readinessWeights.soil)+category(uiLang==='hi'?'सिंचाई':'Irrigation',s.irrigation,readinessWeights.irrigation)+category(uiLang==='hi'?'इनपुट उपयोग':'Input usage',s.inputs,readinessWeights.inputs);content.innerHTML=`<div class="result"><div class="traffic ${statusClasses[status]}"><span></span><b>${uiLang==='hi'?`तैयारी स्तर: ${statusText}`:`${status} readiness`}</b></div><div class="score" style="--score:${score}%"><strong>${score}</strong></div><h3>${uiLang==='hi'?'तैयारी का स्कोर':'Readiness score'} · 100</h3><p>${uiLang==='hi'?'यह शुरुआती तैयारी आकलन है, कार्बन क्रेडिट की गणना नहीं।':'A readiness estimate only; it does not calculate or sell carbon credits.'}</p><div class="breakdown"><h4>${uiLang==='hi'?'AI तैयारी मॉडल · श्रेणी स्कोर':'Readiness model · category breakdown'}</h4>${categoryList}</div><div class="gap-analysis"><b>${uiLang==='hi'?'गुम जानकारी और कमी का विश्लेषण':'AI gap analysis · missing information'}</b><ul>${actions.length?actions.map(a=>`<li>${a[0]} <strong>+${a[1]} ${uiLang==='hi'?'अंक':'points'}</strong></li>`).join(''):`<li>${uiLang==='hi'?'कोई बड़ा अंतर नहीं; स्थानीय ज़रूरतें जाँचें।':'No major gaps found; confirm local requirements.'}</li>`}</ul></div><div class="todo"><b>${uiLang==='hi'?'आपकी कार्य योजना':'Your action plan'}</b><p>${uiLang==='hi'?'पहले आसान दस्तावेज़ और रिकॉर्ड पूरे करें।':'Start with available documents and regular record keeping.'}</p></div><div class="report-actions"><button class="primary" id="done">${uiLang==='hi'?'नतीजा सहेजें':'Save result on this device'}</button><button class="secondary" id="downloadReport">${uiLang==='hi'?'PDF / प्रिंट रिपोर्ट':'Download / print report'}</button><button class="secondary" id="shareReport">${uiLang==='hi'?'रिपोर्ट साझा करें':'Share report'}</button></div></div>`;document.querySelector('#progress').style.width='100%';answers.result={score,breakdown:s,status,actions,weights:{...readinessWeights}};document.querySelector('#downloadReport').onclick=printReadinessReport;document.querySelector('#shareReport').onclick=async()=>{const text=`HumusIQ farm readiness: ${score}/100 (${status}).`;try{if(navigator.share)await navigator.share({title:'HumusIQ readiness report',text});else if(navigator.clipboard){await navigator.clipboard.writeText(text);toast(uiLang==='hi'?'रिपोर्ट का सार कॉपी हुआ।':'Report summary copied.')}else window.prompt(uiLang==='hi'?'रिपोर्ट कॉपी करें':'Copy report summary',text)}catch(e){}};document.querySelector('#done').onclick=()=>{localStorage.setItem('terraAssessment',JSON.stringify(answers));const session=getTerraSession();if(session?.role==='user')localStorage.setItem('terraAssessment:'+session.email,JSON.stringify(answers));const records=JSON.parse(localStorage.getItem('terraAssessments')||'[]'),record={email:session&&session.role==='user'?session.email:'',name:answers.profile.name||(session&&session.name)||'Farmer',village:answers.profile.village||'',district:answers.profile.district||'',area:answers.land.area||'',result:answers.result,verificationStatus:'pending',updated:new Date().toISOString()},key=record.email||('name:'+record.name.toLowerCase()),index=records.findIndex(r=>(r.email||('name:'+String(r.name||'').toLowerCase()))===key);if(index>=0){record.verificationStatus=records[index].verificationStatus||'pending';records[index]=record}else records.push(record);localStorage.setItem('terraAssessments',JSON.stringify(records));syncFarmerRecord(session,answers);updateDashboard(score,s,status,actions);renderFarmerPages();closeModal();toast(uiLang==='hi'?'तैयारी नतीजा सहेजा गया।':'Readiness result saved.')}}

function openModal() { const session = getTerraSession(); if (!session || session.role !== 'user') { openAuth('login'); document.querySelector('#authFeedback').textContent = uiLang === 'hi' ? 'तैयारी जाँचने के लिए पहले लॉग इन करें या खाता बनाएँ।' : 'Log in or create a farmer account before starting your readiness check.'; return } step = 0; modal.classList.add('open'); document.body.style.overflow = 'hidden'; render(true) } function closeModal() { if ('speechSynthesis' in window) speechSynthesis.cancel(); modal.classList.remove('open'); document.body.style.overflow = '' } function toast(s) { let t = document.querySelector('#toast'); t.textContent = s; t.classList.add('show'); setTimeout(() => t.classList.remove('show'), 2800) } const farmerGuide = document.querySelector('.guide'); farmerGuide.onclick = () => { if (modal.classList.contains('open')) readModal(); else openModal() }; farmerGuide.onkeydown = e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); farmerGuide.click() } }; document.querySelector('#close').onclick = closeModal; modal.onclick = e => { if (e.target === modal) closeModal() }; document.addEventListener('keydown', e => { if (e.key === 'Escape') closeModal() });
let cropPayload = null, cropPrediction = null;
const cropForm = document.querySelector('#cropAnalysisForm');
function escapeCropText(value){return String(value ?? '').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function cropDisplayLabel(key){const labels={nitrogen:uiLang==='hi'?'नाइट्रोजन (N)':'Nitrogen (N)',phosphorus:uiLang==='hi'?'फॉस्फोरस (P)':'Phosphorus (P)',potassium:uiLang==='hi'?'पोटैशियम (K)':'Potassium (K)',ph:uiLang==='hi'?'मिट्टी pH':'Soil pH',temperature:uiLang==='hi'?'तापमान':'Temperature',rainfall:uiLang==='hi'?'बारिश':'Rainfall'};return labels[key]||key}
function cropValueLabel(key,value){const units={nitrogen:'kg/ha',phosphorus:'kg/ha',potassium:'kg/ha',ph:'',temperature:'°C',rainfall:'mm'};return escapeCropText(value)+(units[key]?' '+(uiLang==='hi'&&units[key]==='kg/ha'?'किग्रा/हेक्टेयर':units[key]):'')}
function cropStatusText(value){const v=String(value||'');return uiLang==='hi'?({Low:'कम',High:'अधिक',Moderate:'मध्यम'}[v]||v):v}
function renderCropAnalysis(){if(!cropPayload||!cropPrediction)return;const p=cropPayload,r=cropPrediction,hiLang=uiLang==='hi',keys=['nitrogen','phosphorus','potassium','ph'];const soilTitles={nitrogen:hiLang?'नाइट्रोजन':'Nitrogen',phosphorus:hiLang?'फॉस्फोरस':'Phosphorus',potassium:hiLang?'पोटैशियम':'Potassium',ph:hiLang?'मिट्टी pH':'Soil pH'};const climateStatus=r.climate?.rainfall||'—';const summary=[...keys.map(k=>`<div><span>${cropDisplayLabel(k)}</span><strong>${cropValueLabel(k,p[k])}</strong></div>`),`<div><span>${cropDisplayLabel('temperature')}</span><strong>${cropValueLabel('temperature',p.temperature)}</strong></div>`,`<div><span>${cropDisplayLabel('rainfall')}</span><strong>${cropValueLabel('rainfall',p.rainfall)}</strong></div>`].join('');const soil=keys.map(k=>{const state=r.soil?.[k]||'—';return `<article class="signal-card"><div class="signal-top"><span>${soilTitles[k]}</span><b class="status-badge ${escapeCropText(String(state).toLowerCase())}">${cropStatusText(state)}</b></div><strong>${cropValueLabel(k,p[k])}</strong><div class="signal-track"><span class="signal-${escapeCropText(String(state).toLowerCase())}"></span></div></article>`}).join('');const recs=(r.recommendations||[]).map((item,i)=>`<article class="recommendation-item"><span class="recommendation-number">0${i+1}</span><p>${escapeCropText(item)}</p></article>`).join('');const statusClass=String(climateStatus).toLowerCase();document.querySelector('#cropResults').innerHTML=`<section class="card prediction-card"><div class="prediction-copy"><span class="demo-chip">${hiLang?'डेमो AI परिणाम':'Mock AI result'}</span><p class="result-overline">${hiLang?'सुझाई गई फसल':'Recommended crop'}</p><h3>🌱 ${escapeCropText(r.recommendedCrop)}</h3><p>${hiLang?'दी गई जानकारी के आधार पर ':'Based on the submitted parameters, '} ${escapeCropText(r.recommendedCrop)} ${hiLang?'सबसे उपयुक्त फसल का अनुमान है।':'is predicted as the most suitable crop.'}</p><span class="prediction-caution">${hiLang?'AI का अनुमान · गारंटी नहीं':'AI prediction · not guaranteed'}</span></div><div class="confidence-ring" style="--confidence:${Math.max(0,Math.min(100,Number(r.confidence)||0))}%"><div><strong>${escapeCropText(r.confidence)}%</strong><span>${hiLang?'भरोसे का स्तर':'Confidence'}</span></div></div></section><section class="crop-section"><div class="section-title"><span class="crop-step">02</span><div><h3>${hiLang?'मिट्टी का विश्लेषण':'Soil analysis'}</h3><p>${hiLang?'दिए गए मान और मॉडल के स्थिति संकेत':'Submitted values and model status signals'}</p></div></div><div class="signal-grid">${soil}</div></section><section class="crop-section"><div class="section-title"><span class="crop-step">03</span><div><h3>${hiLang?'मौसम की स्थिति':'Climate conditions'}</h3><p>${hiLang?'तापमान और बारिश की जानकारी':'Temperature and rainfall inputs'}</p></div></div><div class="climate-grid"><article class="climate-card"><span>☀️</span><div><small>${cropDisplayLabel('temperature')}</small><strong>${cropValueLabel('temperature',p.temperature)}</strong></div></article><article class="climate-card"><span>🌧️</span><div><small>${cropDisplayLabel('rainfall')}</small><strong>${cropValueLabel('rainfall',p.rainfall)}</strong></div></article><article class="climate-card rainfall-status"><span>💧</span><div><small>${hiLang?'बारिश की स्थिति':'Rainfall status'}</small><strong class="status-badge ${escapeCropText(statusClass)}">${cropStatusText(climateStatus)}</strong></div></article></div></section><section class="card engine-card"><div class="section-title"><span class="crop-step">04</span><div><h3>${hiLang?'HumusIQ सुझाव प्रणाली':'HumusIQ Recommendation Engine'}</h3><p>${hiLang?'चार प्रकार की जानकारी मिलकर आपके अगले कदम सुझाती है':'Four signals combine to shape your next steps'}</p></div></div><div class="engine-flow"><div>${hiLang?'खेत की जानकारी':'Farmer data'}</div><b>+</b><div>${hiLang?'AI अनुमान':'AI prediction'}</div><b>+</b><div>${hiLang?'मिट्टी':'Soil analysis'}</div><b>+</b><div>${hiLang?'मौसम':'Climate conditions'}</div><b class="flow-down">↓</b><strong>${hiLang?'आपके खेत के लिए सुझाव':'Personalized recommendation'}</strong></div><div class="recommendation-list"><div class="section-title compact"><div><h4>${hiLang?'आपके अगले कदम':'Personalized farmer recommendations'}</h4><p>${hiLang?'इसे योजना बनाने के लिए इस्तेमाल करें; स्थानीय विशेषज्ञ से पुष्टि करें।':'Use these as planning guidance and confirm with a local expert.'}</p></div></div><article class="recommendation-item crop-recommendation"><span>🌱</span><p>${hiLang?'दी गई जानकारी के आधार पर ':'Based on the submitted parameters, '}${escapeCropText(r.recommendedCrop)} ${hiLang?'सबसे उपयुक्त फसल का अनुमान है।':'is predicted as the most suitable crop.'}</p></article>${recs}</div></section><div class="crop-details-grid"><section class="card"><div class="section-title"><span class="crop-step">05</span><div><h3>${hiLang?'खेत की जानकारी का सार':'Farm data summary'}</h3><p>${hiLang?'ये मान इस विश्लेषण में भेजे गए थे':'Values submitted for this analysis'}</p></div></div><div class="summary-grid">${summary}</div></section><section class="card explain-card"><h3>${hiLang?'यह सुझाव क्यों?':'Why this recommendation?'}</h3><p>${hiLang?'HumusIQ आपकी दी गई मिट्टी और मौसम की जानकारी को फसल अनुमान मॉडल से जाँचता है। यह मॉडल के सीखे पैटर्न से मेल खाने वाली फसल बताता है, फिर अगले काम के सुझाव जोड़ता है।':'HumusIQ analyzes the submitted soil and climate readings with the crop prediction model. It identifies a crop matching patterns learned during training, then combines that prediction with soil and climate signals to suggest practical next steps.'}</p><p class="crop-disclaimer">${hiLang?'ये डेमो परिणाम उदाहरण हैं। फसल की उपयुक्तता स्थानीय कृषि विशेषज्ञ और मिट्टी जाँच से पक्की करें।':'Demo results are illustrative. Confirm crop suitability with local agricultural experts and verified soil reports.'}</p></section></div>`;document.querySelector('#cropResults').hidden=false}
cropForm.addEventListener('submit',async e=>{e.preventDefault();const data=new FormData(cropForm),payload={nitrogen:Number(data.get('nitrogen')),phosphorus:Number(data.get('phosphorus')),potassium:Number(data.get('potassium')),ph:Number(data.get('ph')),temperature:Number(data.get('temperature')),rainfall:Number(data.get('rainfall'))};const valid=Object.values(payload).every(Number.isFinite)&&payload.nitrogen>=0&&payload.nitrogen<=2000&&payload.phosphorus>=0&&payload.phosphorus<=2000&&payload.potassium>=0&&payload.potassium<=2000&&payload.ph>=0&&payload.ph<=14&&payload.temperature>=-10&&payload.temperature<=60&&payload.rainfall>=0&&payload.rainfall<=2000;if(!valid){cropForm.reportValidity();document.querySelector('#cropValidation').textContent=uiLang==='hi'?'कृपया सभी संख्याएँ जाँचें। तय सीमा से बाहर जानकारी न दें।':'Check each number and stay within the allowed ranges.';return}document.querySelector('#cropValidation').textContent='';cropPayload=payload;cropPrediction=null;const button=document.querySelector('#analyzeCrop'),processing=document.querySelector('#aiProcessing');button.disabled=true;button.classList.add('is-loading');document.querySelector('#cropEmpty').hidden=true;document.querySelector('#cropResults').hidden=true;document.querySelector('#cropError').hidden=true;processing.hidden=false;try{cropPrediction=await window.HumusIQCropApi.predictCrop(payload);renderCropAnalysis()}catch(err){const box=document.querySelector('#cropError');box.hidden=false;box.textContent=(uiLang==='hi'?'विश्लेषण पूरा नहीं हो सका: ':'Analysis could not be completed: ')+(err?.message||(uiLang==='hi'?'फसल विश्लेषण सेवा से संपर्क नहीं हो सका। फिर कोशिश करें।':'Could not connect to the crop analysis service. Try again.'))}finally{processing.hidden=true;button.disabled=false;button.classList.remove('is-loading')}});
function setFarmerPage(page){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.page===page));document.querySelectorAll('.dashpage').forEach(x=>x.classList.toggle('active',x.id==='page-'+page));document.querySelector('#dashboard').scrollIntoView({behavior:'smooth',block:'start'});if('speechSynthesis'in window)speechSynthesis.cancel();listenBtn.textContent=uiLang==='hi'?'🔊 सुनें':'🔊 Listen';voiceBubble.textContent=uiLang==='hi'?'चुना हुआ पेज सुनने के लिए Listen दबाएँ।':'Tap Listen to hear this page.';voiceBubble.classList.add('show')}
const tabs=[...document.querySelectorAll('.tab')];tabs.forEach(t=>t.onclick=()=>{if(t.dataset.page==='crop-ai'&&getTerraSession()?.role!=='user'){openAuth('login');document.querySelector('#authFeedback').textContent=uiLang==='hi'?'फसल विश्लेषण के लिए पहले किसान खाते में लॉग इन करें।':'Log in as a farmer to use crop analysis.';return}setFarmerPage(t.dataset.page)});
document.querySelector('#newAssessmentNav').onclick=()=>{if(getTerraSession()?.role!=='user'){openAuth('login');return}openModal()};
