function openAuth(mode = 'login') { document.querySelector('#adminScreen').classList.remove('open'); document.querySelector('#verifierScreen').classList.remove('open'); document.querySelector('#authScreen').classList.add('open'); document.body.style.overflow = 'hidden'; setAuthMode(mode) }
function closeAuth() { document.querySelector('#authScreen').classList.remove('open'); document.body.style.overflow = '' }
function goFarmerDashboard() { closeAuth(); document.querySelector('#adminScreen').classList.remove('open'); document.querySelector('#verifierScreen').classList.remove('open'); document.body.style.overflow = ''; refreshSessionUI(); setFarmerPage('overview');document.querySelector('#dashboard').scrollIntoView({behavior:'smooth',block:'start'}) }
