function renderAdminDashboard() { const accounts = JSON.parse(localStorage.getItem('terraAccounts') || '[]'), records = JSON.parse(localStorage.getItem('terraAssessments') || '[]'); document.querySelector('#adminUsers').textContent = accounts.length; document.querySelector('#adminAssessments').textContent = records.length; const avg = records.length ? Math.round(records.reduce((sum, r) => sum + (r.result?.score || 0), 0) / records.length) : null; document.querySelector('#adminAverage').textContent = avg === null ? '—' : avg + '%'; const lights={High:0,Medium:0,Low:0};records.forEach(r=>{const x=({Green:'High',Yellow:'Medium',Red:'Low'})[r.result?.status]||r.result?.status;if(lights[x]!==undefined)lights[x]++});document.querySelector('#adminLights').textContent=lights.High+' / '+lights.Medium+' / '+lights.Low; drawAdminRows() }
function drawAdminRows() { const records = JSON.parse(localStorage.getItem('terraAssessments') || '[]').sort((a, b) => new Date(b.updated) - new Date(a.updated)), query = document.querySelector('#adminSearch').value.toLowerCase(), filtered = records.filter(r => [r.name, r.email, r.village, r.district].join(' ').toLowerCase().includes(query)), tbody = document.querySelector('#adminRows'); tbody.replaceChildren(); filtered.forEach(r => { const tr = document.createElement('tr'), cells = [r.name || 'Farmer', r.village + (r.village && r.district ? ' / ' : '') + (r.district || ''), r.area ? (r.area + ' acres') : '—', r.result?.score === undefined ? '—' : r.result.score + '%', r.result?.status || '—', r.result?.breakdown?.practice ?? '—',r.result?.breakdown?.land??'—',r.result?.breakdown?.documents??r.result?.breakdown?.docs??'—',r.result?.breakdown?.soil??'—',r.result?.breakdown?.irrigation??'—',r.result?.breakdown?.inputs??'—',r.updated ? new Date(r.updated).toLocaleDateString() : '—']; cells.forEach((v, i) => { const td = document.createElement('td'); td.textContent = v; if (i === 4 && r.result?.status) { const badge = document.createElement('span'); badge.className='statuspill '+(({High:'green',Medium:'yellow',Low:'red'})[r.result.status]||r.result.status.toLowerCase());badge.textContent=uiLang==='hi'?({Green:'हरा',Yellow:'पीला',Red:'लाल',High:'उच्च',Medium:'मध्यम',Low:'कम'}[r.result.status]||r.result.status):r.result.status; td.replaceChildren(badge) } tr.appendChild(td) }); tbody.appendChild(tr) }); document.querySelector('#adminEmpty').hidden = filtered.length > 0 }
function goVerifierDashboard(){closeAuth();document.querySelector('#adminScreen').classList.remove('open');document.body.style.overflow='hidden';document.querySelector('#verifierScreen').classList.add('open');renderVerifierDashboard()}
function renderVerifierDashboard(){const records=JSON.parse(localStorage.getItem('terraAssessments')||'[]');document.querySelector('#verifierTotal').textContent=records.length;document.querySelector('#verifierPending').textContent=records.filter(r=>(r.verificationStatus||'pending')==='pending').length;document.querySelector('#verifierApproved').textContent=records.filter(r=>r.verificationStatus==='approved').length;document.querySelector('#verifierNeedsInfo').textContent=records.filter(r=>r.verificationStatus==='needs-info').length;const body=document.querySelector('#verifierRows');body.replaceChildren();records.slice().sort((a,b)=>new Date(b.updated)-new Date(a.updated)).forEach(r=>{const tr=document.createElement('tr'),status=r.verificationStatus||'pending',values=[r.name||'Farmer',[r.village,r.district].filter(Boolean).join(', ')||'—',r.area?(r.area+' acres'):'—',r.result?.score===undefined?'—':r.result.score+'/100',status];values.forEach((v,i)=>{const td=document.createElement('td');td.textContent=i===4&&uiLang==='hi'?({'pending':'समीक्षा बाकी','approved':'स्वीकृत','needs-info':'और जानकारी चाहिए'}[v]||v):v;tr.appendChild(td)});const td=document.createElement('td'),approve=document.createElement('button'),more=document.createElement('button');approve.className='secondary review-action';approve.textContent=uiLang==='hi'?'स्वीकृत करें':'Approve';approve.dataset.review='approved';approve.dataset.email=r.email;approve.dataset.name=r.name;more.className='secondary review-action';more.textContent=uiLang==='hi'?'जानकारी माँगें':'Request info';more.dataset.review='needs-info';more.dataset.email=r.email;more.dataset.name=r.name;td.append(approve,more);tr.appendChild(td);body.appendChild(tr)});document.querySelector('#verifierEmpty').hidden=records.length>0}
function updateVerificationStatus(e){const btn=e.target.closest('[data-review]');if(!btn)return;const records=JSON.parse(localStorage.getItem('terraAssessments')||'[]'),key=btn.dataset.email||('name:'+String(btn.dataset.name||'').toLowerCase()),r=records.find(x=>(x.email||('name:'+String(x.name||'').toLowerCase()))===key);if(r){r.verificationStatus=btn.dataset.review;r.verifiedAt=new Date().toISOString();localStorage.setItem('terraAssessments',JSON.stringify(records));renderVerifierDashboard()}}
function loadFarmerAccount(user) { const empty = { profile: { name: user.name, email: user.email }, land: {}, crops: [], practices: [], inputs: [], irrigation: [], soil: [], water: [], documents: [], boundary: [] }; try { answers = JSON.parse(localStorage.getItem('terraAssessment:' + user.email) || 'null') || empty; answers={...empty,...answers,profile:{...empty.profile,...answers.profile},land:{...empty.land,...answers.land}}; ['crops','practices','inputs','irrigation','soil','water','documents','boundary'].forEach(k=>{if(!Array.isArray(answers[k]))answers[k]=[]}) } catch (e) { answers = empty } if (answers.result) updateDashboard(answers.result.score, answers.result.breakdown, answers.result.status, answers.result.actions, answers.result.weights); else { document.querySelector('#metricScore').textContent = '—'; document.querySelector('#metricPractices').textContent = '0'; document.querySelector('#dashReadiness').className = 'readiness-pill pending'; document.querySelector('#dashReadiness').textContent = uiLang === 'hi' ? 'अभी आकलन नहीं हुआ · शुरू करने के लिए खेत की जाँच करें।' : 'Not assessed yet · Start the farm check to begin.'; document.querySelector('#dashMeter').style.width = '0%'; document.querySelector('#dashboardBreakdown').replaceChildren(); document.querySelector('#dashboardActions').replaceChildren();renderFarmerPages() } }
