document.querySelector('#userLoginForm').onsubmit = async e => { e.preventDefault(); const data = new FormData(e.currentTarget), email = String(data.get('email')).trim().toLowerCase(), password = String(data.get('password')), users = JSON.parse(localStorage.getItem('terraAccounts') || '[]'), user = users.find(u => u.email === email); if (!user) { document.querySelector('#authFeedback').textContent = uiLang === 'hi' ? 'इस ईमेल का खाता नहीं मिला। पहले खाता बनाएँ।' : 'No account found for this email. Create an account first.'; return } const hash = await hashPassword(email, password); if (!hash || hash !== user.passwordHash) { document.querySelector('#authFeedback').textContent = uiLang === 'hi' ? 'ईमेल या पासवर्ड सही नहीं है।' : 'Incorrect email or password.'; return } localStorage.setItem('terraSession', JSON.stringify({ role: 'user', email: user.email, name: user.name })); loadFarmerAccount(user); goFarmerDashboard() };
document.querySelector('#signupForm').onsubmit = async e => { e.preventDefault(); const data = new FormData(e.currentTarget), name = String(data.get('name')).trim(), email = String(data.get('email')).trim().toLowerCase(), password = String(data.get('password')), users = JSON.parse(localStorage.getItem('terraAccounts') || '[]'); if (users.some(u => u.email === email)) { document.querySelector('#authFeedback').textContent = uiLang === 'hi' ? 'यह ईमेल पहले से पंजीकृत है। लॉग इन करें।' : 'Email already registered. Please sign in.'; return } const passwordHash = await hashPassword(email, password); if (!passwordHash) { document.querySelector('#authFeedback').textContent = uiLang === 'hi' ? 'खाता नहीं बन सका; सुरक्षित ब्राउज़र स्टोरेज उपलब्ध नहीं है।' : 'Could not create account because secure browser storage is unavailable.'; return } const user = { name, email, passwordHash, created: new Date().toISOString() }; users.push(user); localStorage.setItem('terraAccounts', JSON.stringify(users)); syncFarmerRecord(user); localStorage.setItem('terraSession', JSON.stringify({ role: 'user', email, name })); loadFarmerAccount(user); goFarmerDashboard(); toast(uiLang === 'hi' ? 'खाता बन गया। आपकी जानकारी इसी ब्राउज़र में रहेगी।' : 'Account created. Your details stay in this browser.') };
