document.querySelector('#adminLoginForm').onsubmit = e => { e.preventDefault(); const data = new FormData(e.currentTarget), email = String(data.get('email')).trim().toLowerCase(), password = String(data.get('password')); if (email === 'admin@humusiq.farm' && password === 'farmadmin123') { localStorage.setItem('terraSession', JSON.stringify({ role: 'admin', email })); refreshSessionUI(); goAdminDashboard() } else document.querySelector('#authFeedback').textContent = uiLang === 'hi' ? 'एडमिन लॉग इन विफल। डेमो जानकारी जाँचें।' : 'Admin sign-in failed. Check the demo credentials.' };
async function hashPassword(email, password) { if (!window.crypto?.subtle) return null; const bytes = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(email + ':terra-local-demo:' + password)); return Array.from(new Uint8Array(bytes), b => b.toString(16).padStart(2, '0')).join('') }
document.querySelector('#exportCsv').onclick = () => { const rows = JSON.parse(localStorage.getItem('terraAssessments') || '[]'), head=['Farmer','Email','Village','District','Area acres','Score','Status','Practices / 25','Land / 15','Documents / 20','Soil / 15','Irrigation / 15','Inputs / 10','Updated'], escape = v => '"' + String(v ?? '').replaceAll('"', '""') + '"', csv = [head, ...rows.map(r => [r.name, r.email, r.village, r.district, r.area, r.result?.score, r.result?.status, r.result?.breakdown?.practice,r.result?.breakdown?.land,r.result?.breakdown?.documents??r.result?.breakdown?.docs,r.result?.breakdown?.soil,r.result?.breakdown?.irrigation,r.result?.breakdown?.inputs,r.updated])].map(row => row.map(escape).join(',')).join('\n'), url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' })), a = document.createElement('a'); a.href = url; a.download = 'humusiq-readiness-assessments.csv'; a.click(); URL.revokeObjectURL(url) };
