let adminData = {}, adminCurrentPage = 'dashboard', lastPredictionSync = '';
function adminToken(){return localStorage.getItem('humusiqAdminToken')||''}
async function apiRequest(url,options){const config={...(options||{}),headers:{'Content-Type':'application/json',...((options&&options.headers)||{})}};if(adminToken())config.headers.Authorization='Bearer '+adminToken();const response=await fetch(url,config);const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||('Request failed ('+response.status+')'));return data}
function adminText(en,hiText){return uiLang==='hi'?hiText:en}
function adminSetStatus(message,isError){const target=document.querySelector('#adminApiStatus');if(target){target.textContent=message;target.classList.toggle('error',!!isError)}}
function adminPageFromPath(){const last=location.pathname.split('/').filter(Boolean).pop(),aliases={'ai-predictions':'predictions','system-settings':'settings'};return aliases[last]||(['dashboard','farmers','farms','assessments','predictions','documents','verification','model-performance','reports','settings'].includes(last)?last:'dashboard')}
async function goAdminDashboard(){closeAuth();document.querySelector('#verifierScreen').classList.remove('open');const token=adminToken();if(!token){openAuth('admin');return}try{await apiRequest('/api/admin/me')}catch(e){localStorage.removeItem('humusiqAdminToken');localStorage.removeItem('terraSession');refreshSessionUI();openAuth('admin');document.querySelector('#authFeedback').textContent=e.message;return}localStorage.setItem('terraSession',JSON.stringify({role:'admin',email:'admin@humusiq.farm'}));document.body.style.overflow='hidden';document.querySelector('#adminScreen').classList.add('open');adminCurrentPage=adminPageFromPath();await renderAdminDashboard()}
async function renderAdminDashboard(){try{adminSetStatus(adminText('Loading API…','API लोड हो रहा है…'));await apiRequest('/api/admin/import-local',{method:'POST',body:JSON.stringify({accounts:JSON.parse(localStorage.getItem('terraAccounts')||'[]').map(function(a){return{email:a.email,name:a.name,created:a.created}}),assessments:JSON.parse(localStorage.getItem('terraAssessments')||'[]')})});const sections=['dashboard','farmers','farms','assessments','predictions','documents','verification','model-performance','reports','settings'];const values=await Promise.all(sections.map(function(section){return apiRequest('/api/admin/'+section)}));sections.forEach(function(section,index){adminData[section]=values[index]});adminSetStatus(adminText('API connected','API जुड़ गया'));renderAdminPage(adminCurrentPage)}catch(e){adminSetStatus(e.message,true);document.querySelector('#adminContent').innerHTML='<div class="admin-error">'+escapeCropText(e.message)+'<p>'+adminText('Check that the Express server is running.','जाँचें कि Express सर्वर चल रहा है।')+'</p><button class="primary" id="adminRetry">'+adminText('Try again','फिर कोशिश करें')+'</button></div>'}}
function adminTable(headers,rows){if(!rows.length)return '<div class="admin-empty-state">'+adminText('No records yet. Farmer data appears here after it syncs to the server.','अभी रिकॉर्ड नहीं हैं। सर्वर से जुड़ने पर किसान की जानकारी यहाँ दिखेगी।')+'</div>';return '<div class="tablewrap admin-tablewrap"><table><thead><tr>'+headers.map(function(h){return '<th>'+h+'</th>'}).join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>'}
function adminCells(values){return '<tr>'+values.map(function(v){return '<td>'+escapeCropText(v==null||v===''?'—':String(v))+'</td>'}).join('')+'</tr>'}
function adminScore(item){return item&&item.result&&item.result.score!==undefined?item.result.score+'%':'—'}
function renderAdminPage(page){adminCurrentPage=page;document.querySelectorAll('.admin-nav').forEach(function(b){b.classList.toggle('active',b.dataset.adminPage===page)});const titleMap={'dashboard':['Dashboard','डैशबोर्ड'],'farmers':['Farmers','किसान'],'farms':['Farms','खेत'],'assessments':['Assessments','आकलन'],'predictions':['AI Predictions','AI अनुमान'],'documents':['Documents','दस्तावेज़'],'verification':['Verification','सत्यापन'],'model-performance':['Model Performance','मॉडल प्रदर्शन'],'reports':['Reports','रिपोर्ट'],'settings':['System Settings','सिस्टम सेटिंग्स']};document.querySelector('#adminPageTitle').textContent=adminText(titleMap[page][0],titleMap[page][1]);document.querySelector('#adminPageSubtitle').textContent=page==='dashboard'?adminText('Farmer readiness and platform activity.','किसान तैयारी और प्लेटफ़ॉर्म गतिविधि।'):adminText('Manage and review HumusIQ prototype records.','HumusIQ प्रोटोटाइप रिकॉर्ड देखें और सँभालें।');const routeName=page==='predictions'?'ai-predictions':page==='settings'?'system-settings':page;history.replaceState({},'',page==='dashboard'?'/admin':'/admin/'+routeName);const data=adminData[page],assessmentRows=(adminData.assessments||[]);let html='';
if(page==='dashboard'){const d=data||{},k=d.readiness||{};html='<div class="adminstats"><article class="adminstat"><span>'+adminText('Total farmers','कुल किसान')+'</span><strong>'+d.farmers+'</strong></article><article class="adminstat"><span>'+adminText('Farms recorded','दर्ज खेत')+'</span><strong>'+d.farms+'</strong></article><article class="adminstat"><span>'+adminText('Completed assessments','पूरे आकलन')+'</span><strong>'+d.assessments+'</strong></article><article class="adminstat"><span>'+adminText('Average readiness','औसत तैयारी')+'</span><strong>'+(d.averageScore===null?'—':d.averageScore+'%')+'</strong></article><article class="adminstat"><span>'+adminText('Pending verification','सत्यापन बाकी')+'</span><strong>'+d.pendingVerification+'</strong></article><article class="adminstat"><span>'+adminText('Prediction records','अनुमान रिकॉर्ड')+'</span><strong>'+d.predictions+'</strong></article></div><section class="admincard"><h2>'+adminText('Readiness traffic lights','तैयारी की स्थिति')+'</h2><div class="admin-light-row"><span>🟢 '+adminText('High','उच्च')+' <b>'+(k.high||0)+'</b></span><span>🟡 '+adminText('Medium','मध्यम')+' <b>'+(k.medium||0)+'</b></span><span>🔴 '+adminText('Low','कम')+' <b>'+(k.low||0)+'</b></span></div></section><section class="admincard"><h2>'+adminText('Recent assessments','हाल के आकलन')+'</h2>'+adminTable(['Farmer','Village / district','Area','Score','Status','Updated'],(d.recent||[]).map(function(r){return adminCells([r.name,[r.village,r.district].filter(Boolean).join(' / '),r.area,adminScore(r),r.result&&r.result.status,r.updated&&new Date(r.updated).toLocaleDateString()])}))+'</section>'}
else if(page==='farmers'){html='<section class="admincard"><div class="admintabletop"><h2>'+adminText('Registered farmers','पंजीकृत किसान')+'</h2><input id="adminSearch" type="search" placeholder="'+adminText('Search name or email','नाम या ईमेल खोजें')+'"></div>'+adminTable(['Name','Email','Created'],(data||[]).map(function(r){return adminCells([r.name,r.email,r.created&&new Date(r.created).toLocaleDateString()])}))+'</section>'}
else if(page==='farms'){html='<section class="admincard"><h2>'+adminText('Farm profiles','खेत की जानकारी')+'</h2>'+adminTable(['Farmer','Location','Area','Crops','Boundary points','Updated'],(data||[]).map(function(r){return adminCells([r.name,[r.village,r.district,r.state].filter(Boolean).join(', '),r.area&&r.area+' acres',(r.crops||[]).map(function(x){return typeof x==='string'?x:String(x)}).join(', '),r.boundaryPoints,r.updated&&new Date(r.updated).toLocaleDateString()])}))+'</section>'}
else if(page==='assessments'){html='<section class="admincard"><div class="admintabletop"><h2>'+adminText('Readiness assessments','तैयारी आकलन')+'</h2><button class="secondary" data-admin-export>↓ '+adminText('Export CSV','CSV डाउनलोड करें')+'</button></div>'+adminTable(['Farmer','Email','Village / district','Area','Score','Traffic light','Practices','Documents','Verification','Updated'],assessmentRows.map(function(r){const b=r.result&&r.result.breakdown||{};return adminCells([r.name,r.email,[r.village,r.district].filter(Boolean).join(' / '),r.area&&r.area+' acres',adminScore(r),r.result&&r.result.status,b.practice,b.documents===undefined?b.docs:b.documents,(r.verificationStatus||'pending'),r.updated&&new Date(r.updated).toLocaleDateString()])}))+'</section>'}
else if(page==='predictions'){html='<section class="admincard"><h2>'+adminText('AI crop predictions','AI फसल अनुमान')+'</h2><p>'+adminText('Informational prototype outputs recorded by the crop demo. They are not agronomic prescriptions.','फसल डेमो के जानकारीपरक नतीजे। ये खेती की विशेषज्ञ सलाह नहीं हैं।')+'</p>'+adminTable(['Suggested crop','Confidence','Source','Created'],(data||[]).map(function(r){return adminCells([r.recommendedCrop,r.confidence+'%',r.source,r.createdAt&&new Date(r.createdAt).toLocaleString()])}))+'</section>'}
else if(page==='documents'){const docNames=['Land documents','Soil test report','Crop and farm records','Field photos','Input receipts','No records yet'];html='<section class="admincard"><h2>'+adminText('Available document checklist','उपलब्ध दस्तावेज़ सूची')+'</h2>'+adminTable(['Farmer','Email','Documents marked available','Review status','Updated'],(data||[]).map(function(r){return adminCells([r.name,r.email,(r.items||[]).map(function(i){return docNames[Number(i)]||String(i)}).join(', '),r.verificationStatus,r.updated&&new Date(r.updated).toLocaleDateString()])}))+'</section>'}
else if(page==='verification'){html='<section class="admincard"><h2>'+adminText('Review queue','समीक्षा सूची')+'</h2><p>'+adminText('Update the review state for each submitted assessment.','हर जमा आकलन की समीक्षा स्थिति बदलें।')+'</p>'+adminTable(['Farmer','Location','Score','Current status','Change status'],(data||[]).map(function(r){return '<tr><td>'+escapeCropText(r.name)+'</td><td>'+escapeCropText([r.village,r.district].filter(Boolean).join(', '))+'</td><td>'+escapeCropText(adminScore(r))+'</td><td>'+escapeCropText(r.verificationStatus||'pending')+'</td><td><select data-verification=\"'+escapeCropText(r.id)+'\"><option value=\"pending\">Pending</option><option value=\"approved\">Approved</option><option value=\"needs-info\">Needs info</option><option value=\"rejected\">Rejected</option></select><input class=\"verification-note\" data-note=\"'+escapeCropText(r.id)+'\" placeholder=\"Review note\"><button class=\"secondary\" data-save-verification=\"'+escapeCropText(r.id)+'\">Save</button></td></tr>'}).join(''))+'</section>';setTimeout(function(){(data||[]).forEach(function(r){const x=document.querySelector('[data-verification=\"'+CSS.escape(r.id)+'\"]');if(x)x.value=r.verificationStatus||'pending'})},0)}
else if(page==='model-performance'){html='<section class=\"admincard model-note\"><span class=\"demo-chip\">'+adminText('Prototype rules','प्रोटोटाइप नियम')+'</span><h2>'+escapeCropText(data&&data.modelName||'HumusIQ readiness rules')+'</h2><p>'+adminText('This prototype applies fixed readiness rules to the farmer answers. It does not predict or verify carbon credits.','यह प्रोटोटाइप किसान के जवाबों पर तैयारी के तय नियम लगाता है। यह कार्बन क्रेडिट का अनुमान या सत्यापन नहीं करता।')+'</p><div class=\"admin-model-grid\"><article><span>'+adminText('Recorded predictions','दर्ज अनुमान')+'</span><b>'+(data&&data.predictionCount||0)+'</b></article><article><span>'+adminText('Completed assessments','पूरे आकलन')+'</span><b>'+(data&&data.assessmentCount||0)+'</b></article><article><span>'+adminText('Model accuracy','मॉडल सटीकता')+'</span><b>—</b></article></div><p>'+adminText('Accuracy is not calculated because no verified outcome dataset is connected.','सत्यापित परिणाम डेटा न होने के कारण सटीकता की गणना नहीं हुई।')+'</p></section>'}
else if(page==='reports'){html='<section class=\"admincard\"><h2>'+adminText('Platform report','प्लेटफ़ॉर्म रिपोर्ट')+'</h2><p>'+adminText('Generated','तैयार समय')+': '+escapeCropText(data&&new Date(data.generatedAt).toLocaleString())+'</p><div class=\"admin-model-grid\"><article><span>'+adminText('Farmers','किसान')+'</span><b>'+(data&&data.farmerCount||0)+'</b></article><article><span>'+adminText('Farms','खेत')+'</span><b>'+(data&&data.farmCount||0)+'</b></article><article><span>'+adminText('Assessments','आकलन')+'</span><b>'+(data&&data.assessmentCount||0)+'</b></article><article><span>'+adminText('AI predictions','AI अनुमान')+'</span><b>'+(data&&data.predictionCount||0)+'</b></article></div><button class=\"primary\" data-admin-export>'+adminText('Download assessments CSV','आकलन CSV डाउनलोड करें')+'</button></section>'}
else{const settings=data||{};html='<section class=\"admincard admin-settings\"><h2>'+adminText('Platform preferences','प्लेटफ़ॉर्म प्राथमिकताएँ')+'</h2><label>'+adminText('Default language','डिफ़ॉल्ट भाषा')+' <select id=\"settingLanguage\"><option value=\"en\">English</option><option value=\"hi\">हिन्दी</option></select></label><label><input type=\"checkbox\" id=\"settingVoice\"> '+adminText('Enable voice assistance by default','डिफ़ॉल्ट रूप से आवाज़ सहायता चालू करें')+'</label><h3>'+adminText('Readiness score weights (must total 100)','तैयारी स्कोर के अंक (कुल 100)')+'</h3><div class=\"weight-grid\">'+[['practices','Practices'],['land','Land'],['documents','Documents'],['soil','Soil'],['irrigation','Irrigation'],['inputs','Inputs']].map(function(pair){return '<label>'+adminText(pair[1],({practices:'खेती के तरीके',land:'ज़मीन',documents:'दस्तावेज़',soil:'मिट्टी',irrigation:'सिंचाई',inputs:'इनपुट'})[pair[0]])+'<input type=\"number\" min=\"0\" max=\"100\" data-weight=\"'+pair[0]+'\" value=\"'+Number(settings.readinessWeights&&settings.readinessWeights[pair[0]]||0)+'\"></label>'}).join('')+'</div><p class=\"weight-total\" id=\"weightTotal\"></p><button class=\"primary\" id=\"saveSettings\">'+adminText('Save settings','सेटिंग सहेजें')+'</button><p id=\"settingsFeedback\" role=\"status\"></p></section>';setTimeout(function(){document.querySelector('#settingLanguage').value=settings.language||'en';document.querySelector('#settingVoice').checked=settings.voiceEnabled!==false;updateWeightTotal()},0)}
document.querySelector('#adminContent').innerHTML=html;const search=document.querySelector('#adminSearch');if(search)search.oninput=function(){const query=search.value.toLowerCase();document.querySelectorAll('#adminContent tbody tr').forEach(function(row){row.hidden=!row.textContent.toLowerCase().includes(query)})}}
function updateWeightTotal(){const values=Array.from(document.querySelectorAll('[data-weight]')).map(function(x){return Number(x.value)||0});const total=values.reduce(function(a,b){return a+b},0);const el=document.querySelector('#weightTotal');if(el)el.textContent=adminText('Total: ','कुल: ')+total+(total===100?' ✓':' · '+adminText('must equal 100','कुल 100 होना चाहिए'));return total}
async function syncFarmerRecord(account,assessment){if(!account||!account.email)return;try{await fetch('/api/sync',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({account:{email:account.email,name:account.name,created:account.created},assessment:assessment||undefined})})}catch(e){}}
const originalCropRender=renderCropAnalysis;renderCropAnalysis=function(){originalCropRender();if(cropPrediction&&cropPayload){const sig=JSON.stringify([cropPayload,cropPrediction.recommendedCrop]);if(sig!==lastPredictionSync){lastPredictionSync=sig;fetch('/api/predictions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recommendedCrop:cropPrediction.recommendedCrop,confidence:cropPrediction.confidence,source:'prototype-rules',createdAt:new Date().toISOString()})}).catch(function(){})}}};
document.querySelectorAll('.admin-nav').forEach(function(button){button.onclick=function(){renderAdminPage(button.dataset.adminPage)}});
document.querySelector('#adminRefresh').onclick=renderAdminDashboard;
document.querySelector('#adminContent').addEventListener('click',async function(event){if(event.target.id==='adminRetry'){await renderAdminDashboard();return}if(event.target.matches('[data-admin-export]')){const list=adminData.assessments||[],columns=['Farmer','Email','Village','District','Area','Score','Readiness','Verification','Updated'];const escapeCsv=function(value){return '\"'+String(value==null?'':value).replaceAll('\"','\"\"')+'\"'};const rows=[columns,...list.map(function(r){return[r.name,r.email,r.village,r.district,r.area,r.result&&r.result.score,r.result&&r.result.status,r.verificationStatus,r.updated]})];const blob=new Blob([rows.map(function(row){return row.map(escapeCsv).join(',')}).join('\\n')],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='humusiq-admin-assessments.csv';a.click();URL.revokeObjectURL(a.href)}if(event.target.id==='saveSettings'){const feedback=document.querySelector('#settingsFeedback');const weights={};document.querySelectorAll('[data-weight]').forEach(function(x){weights[x.dataset.weight]=Number(x.value)});if(updateWeightTotal()!==100){feedback.textContent=adminText('Readiness weights must total 100.','तैयारी के अंकों का कुल योग 100 होना चाहिए।');return}try{adminData.settings=await apiRequest('/api/admin/settings',{method:'PATCH',body:JSON.stringify({language:document.querySelector('#settingLanguage').value,voiceEnabled:document.querySelector('#settingVoice').checked,readinessWeights:weights})});feedback.textContent=adminText('Settings saved','सेटिंग सहेजी गई')}catch(e){feedback.textContent=e.message}}if(event.target.matches('[data-save-verification]')){const id=event.target.dataset.saveVerification;try{await apiRequest('/api/admin/verification/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({status:document.querySelector('[data-verification=\"'+CSS.escape(id)+'\"]').value,note:document.querySelector('[data-note=\"'+CSS.escape(id)+'\"]').value})});adminData.verification=await apiRequest('/api/admin/verification');renderAdminPage('verification')}catch(e){adminSetStatus(e.message,true)}}});
document.querySelector('#adminContent').addEventListener('input',function(event){if(event.target.matches('[data-weight]'))updateWeightTotal()});
document.querySelector('#adminLoginForm').onsubmit=async function(event){event.preventDefault();const data=new FormData(event.currentTarget);const feedback=document.querySelector('#authFeedback');feedback.textContent=uiLang==='hi'?'कृपया प्रतीक्षा करें…':'Signing in…';try{const result=await apiRequest('/api/admin/login',{method:'POST',headers:{},body:JSON.stringify({email:data.get('email'),password:data.get('password')})});localStorage.setItem('humusiqAdminToken',result.token);localStorage.setItem('terraSession',JSON.stringify({role:'admin',email:result.email}));refreshSessionUI();await goAdminDashboard()}catch(e){feedback.textContent=e.message}};
document.querySelector('#adminLogout').onclick=async function(){try{await apiRequest('/api/admin/logout',{method:'POST'})}catch(e){}localStorage.removeItem('humusiqAdminToken');localStorage.removeItem('terraSession');document.querySelector('#adminScreen').classList.remove('open');document.body.style.overflow='';history.replaceState({},'','/');refreshSessionUI()};
document.querySelector('#adminBack').onclick=function(){document.querySelector('#adminScreen').classList.remove('open');document.body.style.overflow='';history.replaceState({},'','/');window.scrollTo({top:0,behavior:'smooth'})};
window.addEventListener('popstate',function(){if(document.querySelector('#adminScreen').classList.contains('open'))renderAdminPage(adminPageFromPath())});
fetch('/api/settings').then(function(r){return r.ok?r.json():null}).then(function(settings){if(!settings)return;if(settings.readinessWeights)readinessWeights={...readinessWeights,...settings.readinessWeights};if(!localStorage.getItem('humusiqLanguage')&&['en','hi'].includes(settings.language)&&settings.language!==uiLang){uiLang=settings.language;applyLanguage()}if(settings.voiceEnabled===false){const voice=document.querySelector('.voicebar');if(voice)voice.hidden=true}}).catch(function(){});const initialSession=getTerraSession();if(initialSession&&initialSession.role==='user')loadFarmerAccount(initialSession);if(initialSession&&initialSession.role==='verifier')goVerifierDashboard();if(initialSession&&initialSession.role==='admin')goAdminDashboard(); refreshSessionUI(); applyLanguage();if(location.pathname.indexOf('/admin')===0&&(!initialSession||initialSession.role!=='admin'))setTimeout(function(){openAuth('admin')},0);
